SELECT t1.TRADE_DATE AS `最新行情日期`, t2.COMB_SYMBOL AS `股票代码`, t2.CSNAME AS `股票名称`, ROUND((t1.CLOSE_PRICE * t1.TOTAL_SHARES) / 100000000, 1) AS `总市值(亿美元)` FROM VIEW_US_EOD_EXPR t1 JOIN AMERICAN_STOCK_MAIN t2 ON t1.FIU_ID = t2.FIU_ID WHERE t1.TRADE_DATE = (SELECT MAX(TRADE_DATE) FROM VIEW_US_EOD_EXPR) AND t2.IS_CHINESE_STOCK = '中概股' AND t1.COMB_SYMBOL IS NOT NULL AND t1.FIU_ID IS NOT NULL AND t1.CLOSE_PRICE IS NOT NULL AND t1.TOTAL_SHARES IS NOT NULL ORDER BY (t1.CLOSE_PRICE * t1.TOTAL_SHARES) DESC LIMIT 3;
